import { HttpError } from './http.ts';
import { INVALID_TRACKING_NUMBER, shipmentBodySchema } from './shipmentSchema.ts';

export interface ShipmentInput {
  trackingNumber: string;
  carrier: Carrier;
  serviceLevel: ServiceLevel;
  recipient: Recipient;
}

/** Validates the body of POST /shipments (and the rows of POST /import) against the zod schema. */
export function validateShipmentInput(body: unknown): ShipmentInput {
  const result = shipmentBodySchema.safeParse(body);
  if (!result.success) {
    const issue = result.error.issues[0]!;
    const params = issue.code === 'custom' ? (issue as { params?: { kind?: string } }).params : undefined;
    const code = params?.kind === INVALID_TRACKING_NUMBER ? 'INVALID_TRACKING_NUMBER' : 'VALIDATION_FAILED';
    throw new HttpError(400, code, issue.message);
  }
  const b = result.data;
  const { phone, ...rest } = b.recipient;
  return {
    trackingNumber: b.tracking_number,
    carrier: b.carrier as Carrier,
    serviceLevel: b.service_level as ServiceLevel,
    recipient: { ...rest, ...(phone ? { phone } : {}) },
  };
}
