+  it('normalizes a valid body and applies defaults', () => {
+    const parsed = shipmentBodySchema.parse(body());
+    assert.equal(parsed.tracking_number, 'RR123456785AT');
+    assert.equal(parsed.carrier, 'ATP');
+    assert.equal(parsed.service_level, 'standard');
+    assert.equal(parsed.recipient.name, 'A B');
+    assert.equal(parsed.recipient.country, 'AT');
+    assert.equal(parsed.recipient.phone, undefined);
+  });
+
+  it('maps to the internal ShipmentInput shape', () => {
+    const input = validateShipmentInput(body({ service_level: 'express', recipient: { ...body().recipient, country: 'de', phone: ' 123 ' } }));
+    assert.deepEqual(input, {
+      trackingNumber: 'RR123456785AT',
+      carrier: 'ATP',
+      serviceLevel: 'express',
+      recipient: { name: 'A B', street: 'Weg 1', zip: '1010', city: 'Wien', country: 'DE', phone: '123' },
+    });
+  });
+
+  it('keeps the existing VALIDATION_FAILED messages', () => {
+    assert.deepEqual(rejection(null), { status: 400, code: 'VALIDATION_FAILED', message: 'body must be a JSON object' });
+    assert.equal(rejection([]).message, 'body must be a JSON object');
+    assert.equal(rejection(body({ tracking_number: '  ' })).message, 'tracking_number is required');
+    assert.equal(rejection(body({ carrier: 'FEDEX' })).message, 'carrier must be one of ATP, DHL, DPD, GLS, UPS');
+    assert.equal(rejection(body({ service_level: 'warp' })).message, 'service_level must be one of economy, standard, express');
+    assert.equal(rejection(body({ recipient: undefined })).message, 'recipient is required');
+    assert.equal(rejection(body({ recipient: { name: 'x' } })).message, 'recipient.street is required');
+  });
+
+  it('keeps the German INVALID_TRACKING_NUMBER error for bad ATP numbers', () => {
+    const err = rejection(body({ tracking_number: 'RR123456786AT' }));
